import{_ as i,a0 as t,w as o,s as d,I as n,x as a,a1 as l,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"Docker：使用多階段構建鏡像 | LCTT x X-CMD","titleTemplate":false,"description":"Docker：使用多階段構建鏡像 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Docker：使用多階段構建鏡像 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Docker：使用多階段構建鏡像 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171202 docker - Use multi-stage builds","title":"Docker：使用多階段構建鏡像","tag":"201712","desc":""},"relativePath":"201712/20171202 docker - Use multi-stage builds.md","filePath":"[post].md"}'),c={name:"201712/20171202 docker - Use multi-stage builds.md"};function g(u,s,h,k,b,f){const e=t("Link");return o(),d("div",null,[s[18]||(s[18]=n("h1",{id:"docker-使用多階段構建鏡像",tabindex:"-1"},[a("Docker：使用多階段構建鏡像 "),n("a",{class:"header-anchor",href:"#docker-使用多階段構建鏡像","aria-label":"Permalink to “Docker：使用多階段構建鏡像”"},"​")],-1)),s[19]||(s[19]=n("p",null,"多階段構建是 Docker 17.05 及更高版本提供的新功能。這對致力於優化 Dockerfile 的人來説，使得 Dockerfile 易於閲讀和維護。",-1)),n("blockquote",null,[n("p",null,[s[2]||(s[2]=a("致謝: 特別感謝 ",-1)),l(e,{href:"https://twitter.com/alexellisuk"},{default:p(()=>[...s[0]||(s[0]=[a("Alex Ellis",-1)])]),_:1}),s[3]||(s[3]=a(" 授權使用他的關於 Docker 多階段構建的Blog文章 ",-1)),l(e,{href:"http://blog.alexellis.io/mutli-stage-docker-builds/"},{default:p(()=>[...s[1]||(s[1]=[a("Builder pattern vs. Multi-stage builds in Docker",-1)])]),_:1}),s[4]||(s[4]=a(" 作為以下示例的基礎。",-1))])]),s[20]||(s[20]=r(`<h3 id="在多階段構建之前" tabindex="-1">在多階段構建之前 <a class="header-anchor" href="#在多階段構建之前" aria-label="Permalink to “在多階段構建之前”">​</a></h3><p>關於構建鏡像最具挑戰性的事情之一是保持鏡像體積小巧。 Dockerfile 中的每條指令都會在鏡像中增加一層，並且在移動到下一層之前，需要記住清除不需要的構件。要編寫一個非常高效的 Dockerfile，你通常需要使用 shell 技巧和其它方式來儘可能地減少層數，並確保每一層都具有上一層所需的構件，而其它任何東西都不需要。</p><p>實際上最常見的是，有一個 Dockerfile 用於開發（其中包含構建應用程序所需的所有內容），而另一個裁剪過的用於生產環境，它只包含您的應用程序以及運行它所需的內容。這被稱為“構建器模式”。但是維護兩個 Dockerfile 並不理想。</p><p>下面分別是一個 <code>Dockerfile.build</code> 和遵循上面的構建器模式的 <code>Dockerfile</code> 的例子：</p><p><code>Dockerfile.build</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FROM golang:1.7.3</span></span>
<span class="line"><span>WORKDIR /go/src/github.com/alexellis/href-counter/</span></span>
<span class="line"><span>RUN go get -d -v golang.org/x/net/html</span></span>
<span class="line"><span>COPY app.go .</span></span>
<span class="line"><span>RUN go get -d -v golang.org/x/net/html \\</span></span>
<span class="line"><span>  &amp;&amp; CGO_ENABLED=0 GOOS=linux go build -a -installsuffix cgo -o app .</span></span></code></pre></div><p>注意這個例子還使用 Bash 的 <code>&amp;&amp;</code> 運算符人為地將兩個 <code>RUN</code> 命令壓縮在一起，以避免在鏡像中創建額外的層。這很容易失敗，難以維護。例如，插入另一個命令時，很容易忘記繼續使用 <code>\\</code> 字符。</p><p><code>Dockerfile</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FROM alpine:latest</span></span>
<span class="line"><span>RUN apk --no-cache add ca-certificates</span></span>
<span class="line"><span>WORKDIR /root/</span></span>
<span class="line"><span>COPY app .</span></span>
<span class="line"><span>CMD [&quot;./app&quot;]</span></span></code></pre></div><p><code>build.sh</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span>echo Building alexellis2/href-counter:build</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docker build --build-arg https_proxy=$https_proxy --build-arg http_proxy=$http_proxy \\</span></span>
<span class="line"><span>    -t alexellis2/href-counter:build . -f Dockerfile.build</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docker create --name extract alexellis2/href-counter:build</span></span>
<span class="line"><span>docker cp extract:/go/src/github.com/alexellis/href-counter/app ./app</span></span>
<span class="line"><span>docker rm -f extract</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo Building alexellis2/href-counter:latest</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docker build --no-cache -t alexellis2/href-counter:latest .</span></span>
<span class="line"><span>rm ./app</span></span></code></pre></div><p>當您運行 <code>build.sh</code> 腳本時，它會構建第一個鏡像，從中創建一個容器，以便將該構件複製出來，然後構建第二個鏡像。 這兩個鏡像會佔用您的系統的空間，而你仍然會一個 <code>app</code> 構件存放在你的本地磁盤上。</p><p>多階段構建大大簡化了這種情況！</p><h3 id="使用多階段構建" tabindex="-1">使用多階段構建 <a class="header-anchor" href="#使用多階段構建" aria-label="Permalink to “使用多階段構建”">​</a></h3><p>在多階段構建中，您需要在 Dockerfile 中多次使用 <code>FROM</code> 聲明。每次 <code>FROM</code> 指令可以使用不同的基礎鏡像，並且每次 <code>FROM</code> 指令都會開始新階段的構建。您可以選擇將構件從一個階段複製到另一個階段，在最終鏡像中，不會留下您不需要的所有內容。為了演示這是如何工作的，讓我們調整前一節中的 Dockerfile 以使用多階段構建。</p><p><code>Dockerfile</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FROM golang:1.7.3</span></span>
<span class="line"><span>WORKDIR /go/src/github.com/alexellis/href-counter/</span></span>
<span class="line"><span>RUN go get -d -v golang.org/x/net/html</span></span>
<span class="line"><span>COPY app.go .</span></span>
<span class="line"><span>RUN CGO_ENABLED=0 GOOS=linux go build -a -installsuffix cgo -o app .</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FROM alpine:latest</span></span>
<span class="line"><span>RUN apk --no-cache add ca-certificates</span></span>
<span class="line"><span>WORKDIR /root/</span></span>
<span class="line"><span>COPY --from=0 /go/src/github.com/alexellis/href-counter/app .</span></span>
<span class="line"><span>CMD [&quot;./app&quot;]</span></span></code></pre></div><p>您只需要單一個 Dockerfile。 不需要另外的構建腳本。只需運行 <code>docker build</code> 即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker build -t alexellis2/href-counter:latest .</span></span></code></pre></div><p>最終的結果是和以前體積一樣小的生產鏡像，複雜性顯著降低。您不需要創建任何中間鏡像，也不需要將任何構件提取到本地系統。</p><p>它是如何工作的呢？第二條 <code>FROM</code> 指令以 <code>alpine:latest</code> 鏡像作為基礎開始新的建造階段。<code>COPY --from=0</code> 這一行將剛才前一個階段產生的構件複製到這個新階段。Go SDK 和任何中間構件都被留在那裏，而不會保存到最終的鏡像中。</p><h3 id="命名您的構建階段" tabindex="-1">命名您的構建階段 <a class="header-anchor" href="#命名您的構建階段" aria-label="Permalink to “命名您的構建階段”">​</a></h3><p>默認情況下，這些階段沒有命名，您可以通過它們的整數來引用它們，從第一個 <code>FROM</code> 指令的 0 開始。但是，你可以通過在 <code>FROM</code> 指令中使用 <code>as &lt;NAME&gt;</code> 來為階段命名。以下示例通過命名階段並在 <code>COPY</code> 指令中使用名稱來改進前一個示例。這意味着，即使您的 <code>Dockerfile</code> 中的指令稍後重新排序，<code>COPY</code> 也不會出問題。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FROM golang:1.7.3 as builder</span></span>
<span class="line"><span>WORKDIR /go/src/github.com/alexellis/href-counter/</span></span>
<span class="line"><span>RUN go get -d -v golang.org/x/net/html</span></span>
<span class="line"><span>COPY app.go    .</span></span>
<span class="line"><span>RUN CGO_ENABLED=0 GOOS=linux go build -a -installsuffix cgo -o app .</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FROM alpine:latest</span></span>
<span class="line"><span>RUN apk --no-cache add ca-certificates</span></span>
<span class="line"><span>WORKDIR /root/</span></span>
<span class="line"><span>COPY --from=builder /go/src/github.com/alexellis/href-counter/app .</span></span>
<span class="line"><span>CMD [&quot;./app&quot;]</span></span></code></pre></div><hr>`,25)),n("p",null,[s[6]||(s[6]=a("via: ",-1)),l(e,{href:"https://docs.docker.com/engine/userguide/eng-image/multistage-build/"},{default:p(()=>[...s[5]||(s[5]=[a("https://docs.docker.com/engine/userguide/eng-image/multistage-build/",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=a("作者：",-1)),l(e,{href:"https://docs.docker.com/engine/userguide/eng-image/multistage-build/"},{default:p(()=>[...s[7]||(s[7]=[a("docker",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),l(e,{href:"https://github.com/iron0x"},{default:p(()=>[...s[8]||(s[8]=[a("iron0x",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const C=i(c,[["render",g]]);export{D as __pageData,C as default};
